CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"password" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Project" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Membership" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"role" TEXT NOT NULL DEFAULT 'member',UNIQUE("userId","projectId"));
CREATE TABLE "BoardColumn" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE TABLE "Card" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"position" INTEGER NOT NULL DEFAULT 0,"version" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"columnId" TEXT NOT NULL REFERENCES "BoardColumn"("id") ON DELETE CASCADE);
CREATE TABLE "Comment" ("id" TEXT PRIMARY KEY,"text" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"cardId" TEXT NOT NULL REFERENCES "Card"("id") ON DELETE CASCADE,"authorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Activity" ("id" TEXT PRIMARY KEY,"action" TEXT NOT NULL,"details" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"cardId" TEXT REFERENCES "Card"("id") ON DELETE SET NULL,"actorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"message" TEXT NOT NULL,"read" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "BoardColumn_projectId_idx" ON "BoardColumn"("projectId");CREATE INDEX "Card_columnId_idx" ON "Card"("columnId");CREATE INDEX "Comment_cardId_idx" ON "Comment"("cardId");CREATE INDEX "Activity_projectId_idx" ON "Activity"("projectId");CREATE INDEX "Notification_userId_idx" ON "Notification"("userId");
